const clamp01 = (value) => Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0));
export function projectileSecondaryCeilingPresentation(input, reducedMotion = false, reducedFlash = false) { const stress = clamp01(input.stress), reacquire = clamp01(input.reacquire), weight = clamp01(stress * .82 + (1 - reacquire) * .18 + (input.bossActive ? .08 : 0)); return { trailScale: Math.max(input.critical ? .62 : .48, 1 - weight * (input.critical ? .24 : .42)) * (reducedMotion ? .96 : 1), staleScale: Math.max(.44, 1 - weight * .48) * (reducedFlash ? .95 : 1), canonicalScale: 1, presentationOnly: true }; }
export function impactSecondaryCeilingPresentation(input, reducedFlash = false) { const stress = clamp01(input.stress), reacquire = clamp01(input.reacquire), weight = clamp01(stress * .8 + (1 - reacquire) * .2 + (input.bossActive ? .08 : 0)); return { fillScale: Math.max(input.critical ? .5 : .4, 1 - weight * (input.critical ? .38 : .52)) * (reducedFlash ? .93 : 1), edgeScale: 1, presentationOnly: true }; }
export function hazardSecondaryCeilingPresentation(input, reducedFlash = false) { const stress = clamp01(input.stress), reacquire = clamp01(input.reacquire), weight = clamp01(stress * .82 + (1 - reacquire) * .18); return { fillScale: Math.max(input.critical ? .46 : .36, 1 - weight * (input.telegraph ? .5 : .38)) * (reducedFlash ? .93 : 1), edgeScale: 1, presentationOnly: true }; }
export function specialistSecondaryCeilingPresentation(input, reducedMotion = false) { const stress = clamp01(input.stress), reacquire = clamp01(input.reacquire), action = input.owner === 'special' || input.owner === 'attack', weight = clamp01(stress * .8 + (1 - reacquire) * .2); return { trailScale: Math.max(input.critical ? .58 : action ? .5 : .42, 1 - weight * (input.critical ? .3 : .46)) * (reducedMotion ? .95 : 1), silhouetteScale: 1, presentationOnly: true }; }
export function bossSecondaryCeilingPresentation(input, reducedFlash = false) { const stress = clamp01(input.stress), reacquire = clamp01(input.reacquire), weight = clamp01(stress * .82 + (1 - reacquire) * .18); return { staleScale: Math.max(input.critical ? .52 : .42, 1 - weight * .5) * (reducedFlash ? .94 : 1), telegraphScale: 1, presentationOnly: true }; }
export function secondaryCeilingBudgetPresentation(input, reducedMotion = false, reducedFlash = false) { const critical = clamp01(Math.max(0, input.criticalCount) / 3), crowd = clamp01(input.crowd), stress = clamp01(crowd * .8 + critical * .2 + (input.bossActive ? .06 : 0)); return { stress, secondaryScale: Math.max(.45, 1 - stress * .42) * (reducedMotion ? .97 : 1) * (reducedFlash ? .96 : 1), canonicalScale: 1, presentationOnly: true }; }
